select
admins.*
from admins admins

    and admins.id = #{id}
    and admins.user_name = #{userName}
    and admins.pass_word = #{passWord}
    and admins.head_img = #{headImg}
    and admins.nick_name like concat('%',#{nickName},'%')
    and admins.create_time = #{createTime}


    limit #{current},#{pageSize}

select count(*) from admins admins

    and admins.id = #{id}
    and admins.user_name = #{userName}
    and admins.pass_word = #{passWord}
    and admins.head_img = #{headImg}
    and admins.nick_name like concat('%',#{nickName},'%')
    and admins.create_time = #{createTime}
